  ('Filipino', 8, 'G8-022', 'Nakabubuo ng burador ng sanaysay sa pamamagitan ng tekstong multimodal (gaya ng video o animasyon) - Nakapagtatala ng mga detalye tungkol sa binasang sanaysay', 1, NULL, 'Paglikha at Presentasyon ng Tekstong Multimodal'),
