  ('Values Education', 8, 'G8-001', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pagninilay sa kamalayan sa mga emosyong nararamdaman, kilos, pag-iisip, at reaksiyon ng katawan. - Naiisa-isa ang mga indikasyon ng pagkakaroon ng kamalayan sa mga emosyong nararamdaman.', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 8, 'G8-002', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pagninilay sa kamalayan sa mga emosyong nararamdaman, kilos, pag-iisip, at reaksiyon ng katawan. - Napatutunayan na ang emosyong nararamdaman ay nakatutulong upang lubos na makilala ang sarili at makatugon nang wasto sa mga nararamdaman sa bawat situwasyon tungo sa pagpapaunlad ng sarili at ugnayan sa kapuwa.', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 8, 'G8-003', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pagninilay sa kamalayan sa mga emosyong nararamdaman, kilos, pag-iisip, at reaksiyon ng katawan. - Naipakikita ang pagkilala sa mga emosyong nararamdaman.', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 8, 'G8-004', 'Nakapagsasanay sa pagiging matatag sa pamamagitan ng mga gawaing nagpapakita ng pagpapahalaga sa mga positibong pananaw gabay ang pamilya. - Nailalarawan ang positibong pananaw gabay ang pamilya.', 1, '3 to 4 (10 days)', NULL),
  ('Values Education', 8, 'G8-005', 'Nakapagsasanay sa pagiging matatag sa pamamagitan ng mga gawaing nagpapakita ng pagpapahalaga sa mga positibong pananaw gabay ang pamilya. - Naipaliliwanag na ang positibong pananaw gabay ang pamilya ay may impluwensiya sa kalusugang pangkaisipan at pangkatawan, na nagsisilbing kanlungan sa lahat ng panahon at ito ang naglilinang ng katatagan.', 1, '3 to 4 (10 days)', NULL),
  ('Values Education', 8, 'G8-006', 'Nakapagsasanay sa pagiging matatag sa pamamagitan ng mga gawaing nagpapakita ng pagpapahalaga sa mga positibong pananaw gabay ang pamilya. - Naisasakilos ang mga gawain na nagpapahalaga sa mga positibong pananaw gabay ang pamilya.', 1, '3 to 4 (10 days)', NULL),
  ('Values Education', 8, 'G8-007', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pagiging sensitibo at wastong pagtugon sa pangangailangan ng kapuwa. - Nailalarawan ang mga paraan ng pakikipagkapuwa bilang isang kabataan.', 1, '5 to 6 (10 days)', NULL),
  ('Values Education', 8, 'G8-008', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pagiging sensitibo at wastong pagtugon sa pangangailangan ng kapuwa. - Naipaliliwanag na ang pakikipagkapuwa-tao ay nakaugat sa kalikasan ng tao bilang panlipunang nilalang at naglilinang ng kaniyang kaganapan bilang tao sa pamamagitan ng paglilingkod sa kapuwa na indikasyon ng pagmamahal.', 1, '5 to 6 (10 days)', NULL),
  ('Values Education', 8, 'G8-009', 'Nakapagsasanay sa pagiging mapagmalasakit sa pamamagitan ng pagiging sensitibo at wastong pagtugon sa pangangailangan ng kapuwa. - Nailalapat ang mga paraan ng pakikipagkapuwa bilang isang kabataan.', 1, '5 to 6 (10 days)', NULL),
  ('Values Education', 8, 'G8-010', 'Nakapagsasanay sa paggalang sa buhay sa pamamagitan ng pag-iwas sa mga gawain at ugnayan na nakasasama sa katawan. - Natutukoy ang mga paraan ng pag-iingat sa sarili gabay ang pananampalataya.', 1, '7 to 8 (10 days)', NULL),
  ('Values Education', 8, 'G8-011', 'Nakapagsasanay sa paggalang sa buhay sa pamamagitan ng pag-iwas sa mga gawain at ugnayan na nakasasama sa katawan. - Naipaliliwanag na ang pananampalataya bilang gabay sa pag-iingat sa sarili ay pagpapanatili ng ugnayan sa Diyos at pagtiyak upang lubos na mapahalagahan ang buhay at makamit ang layunin ng kaniyang pagkalikha.', 1, '7 to 8 (10 days)', NULL),
  ('Values Education', 8, 'G8-012', 'Nakapagsasanay sa paggalang sa buhay sa pamamagitan ng pag-iwas sa mga gawain at ugnayan na nakasasama sa katawan. - Naisasakilos ang mga paraan ng pag-iingat sa sarili gabay ang pananampalataya.', 1, '7 to 8 (10 days)', NULL),
  ('Values Education', 8, 'G8-013', 'Nakapagsasanay sa pagiging mapagpasalamat sa pamamagitan ng pagpapahayag ng mga papuri at kabutihan ng Diyos batay sa relihiyon o paniniwalang kinabibilangan. - Naiisa-isa ang mga sariling paraan ng pagdakila sa Diyos.', 1, '9 to 10 (10 days)', NULL),
  ('Values Education', 8, 'G8-014', 'Nakapagsasanay sa pagiging mapagpasalamat sa pamamagitan ng pagpapahayag ng mga papuri at kabutihan ng Diyos batay sa relihiyon o paniniwalang kinabibilangan. - Naipaliliwanag na ang mga sariling paraan ng pagdakila sa Diyos ay pagkilala sa Kaniya at pagpapasalamat sa lahat ng mga biyayang tinatamasa.', 1, '9 to 10 (10 days)', NULL),
  ('Values Education', 8, 'G8-015', 'Nakapagsasanay sa pagiging mapagpasalamat sa pamamagitan ng pagpapahayag ng mga papuri at kabutihan ng Diyos batay sa relihiyon o paniniwalang kinabibilangan. - Nakapaglalapat ng mga sariling paraan ng pagdakila sa Diyos batay sa relihiyon o paniniwalang kinabibilangan.', 1, '9 to 10 (10 days)', NULL),
