  ('Values Education', 8, 'G8-042', 'Naisasabuhay ang pananampalataya sa pamamagitan ng pagkilala sa presensiya ng Diyos sa kinabibilangang pamilya. - Nailalapat ang mga paraan ng pagkilala sa presensiya ng Diyos sa loob ng pamilya.', 2, '9 to 10 (8 days)', NULL),
  ('Values Education', 8, 'G8-043', 'Nakapagsasanay sa pagiging mapamaraan (resourceful) sa pamamagitan ng pagtatanim, pagbuburo at iba pang kaugnay na gawain nang may pagsasaalang-alang sa kalikasan. - Natutukoy ang mga tugon ng pamilya sa mga pangangailangang pisyolohikal ( hal. pagtatanim ng gulay, pagbuburo, at iba pang kaugnay na gawain).', 2, '11 (5 days)', NULL),
  ('Values Education', 8, 'G8-044', 'Nakapagsasanay sa pagiging mapamaraan (resourceful) sa pamamagitan ng pagtatanim, pagbuburo at iba pang kaugnay na gawain nang may pagsasaalang-alang sa kalikasan. - Naipaliliwanag na ang mga tugon ng pamilya sa mga pangagailangang pisyolohikal gaya ng pagtatanim, pagbuburo at iba pang kaugnay na gawain, bilang pinagkukunan ng pagkain ay paraan upang matugunan ang kanilang pangangailangan gamit ang kakayahan at taglay na resorses.', 2, '11 (5 days)', NULL),
  ('Values Education', 8, 'G8-045', 'Nakapagsasanay sa pagiging mapamaraan (resourceful) sa pamamagitan ng pagtatanim, pagbuburo at iba pang kaugnay na gawain nang may pagsasaalang-alang sa kalikasan. - Naisasakilos ang mga paraan sa pagtugon ng pamilya sa mga pangangailangang pisyolohikal na may pagsasaalang-alang sa kalikasan.', 2, '11 (5 days)', NULL),
  ('Values Education', 8, 'G8-046', 'Nakapagsasanay sa nasyonalismo sa pamamagitan ng paghahalaw ng mga virtue na ipinakita ng mga bayani at nasasalamin sa mga makasaysayang pagdiriwang. - Nakakikilala ng mga paraan sa paggunita ng pamilya sa mga makasaysayang pagdiriwang.', 2, '12 to 13 (8 days)', NULL),
  ('Values Education', 8, 'G8-047', 'Nakapagsasanay sa nasyonalismo sa pamamagitan ng paghahalaw ng mga virtue na ipinakita ng mga bayani at nasasalamin sa mga makasaysayang pagdiriwang. - Naipaliliwanag na ang paggunita ng pamilya sa mga makasaysayang pagdiriwang ay nakapagpapaunlad ng kamalayan sa mga kabayanihan ng mga magiting na Pilipino at mahahalagang pangyayari upang bigyang- pugay ang mga ambag ng mga ito sa bansa.', 2, '12 to 13 (8 days)', NULL),
  ('Values Education', 8, 'G8-048', 'Nakapagsasanay sa nasyonalismo sa pamamagitan ng paghahalaw ng mga virtue na ipinakita ng mga bayani at nasasalamin sa mga makasaysayang pagdiriwang. - Nailalapat ang sariling mga paraan ng paggunita ng pamilyang kinabibilangan sa mga makasaysayang pagdiriwang ayon sa kanilang kakayahan.', 2, '12 to 13 (8 days)', NULL)
) AS v(area, grade_level, lc_code, competency_text, term, week, domain)
JOIN procurements.sms_learning_areas a ON lower(btrim(a.name)) = lower(btrim(v.area))
ON CONFLICT (learning_area_id, grade_level, lc_code) DO NOTHING;

/* Verification: after all 22 parts, seeded_entries = 6718. */
SELECT count(*) AS seeded_entries,
       count(DISTINCT learning_area_id) AS learning_areas
FROM procurements.sms_competency_catalogue
WHERE lc_code ~ '^(K|G[0-9]+)-[0-9]{3}$';
